package com.servicerca.security; import com.servicerca.model.User;import org.springframework.security.core.*;import org.springframework.security.core.userdetails.UserDetails;import java.util.*; public record SecurityUser(User user) implements UserDetails{public Collection<? extends GrantedAuthority>getAuthorities(){return List.of();}public String getPassword(){return user.getPasswordHash();}public String getUsername(){return user.getEmail();}public boolean isEnabled(){return user.getDeletedAt()==null;}}
